// 독립 승인 원장을 재사용하는 REVIEW4 공식 투영. 새 승인·후보 생성은 하지 않는다.
import fs from 'node:fs';import assert from 'node:assert/strict';import {isDeepStrictEqual} from 'node:util';import {execFileSync} from 'node:child_process';
import {parseFeatureRows,writeImplementationManifest} from '<repo>/scripts/internal/feature_implementation_manifest_lib.mjs';
import {applyApprovedReview4SemanticClosure} from '<repo>/scripts/internal/feature_semantic_review4_apply.mjs';
const rootDir='<repo>';
const read=f=>JSON.parse(fs.readFileSync(rootDir+'/'+f,'utf8'));
const inventory='docs/project-feature-test-inventory.md',manifestPath='test/fixtures/project_feature_implementation_evidence.json';
const original=execFileSync('git',['show','HEAD:'+inventory],{cwd:rootDir,encoding:'utf8'}),inventoryText=fs.readFileSync(rootDir+'/'+inventory,'utf8');
const rows=parseFeatureRows(inventoryText);assert.equal(rows.length,986);assert(isDeepStrictEqual(rows,parseFeatureRows(original)),'기능 정의 변경은 이 갱신 범위 아님');
const manifest=read(manifestPath);
const next=applyApprovedReview4SemanticClosure({rootDir,inventoryText,rows,manifest,
 audit:read('test/fixtures/v390_review4_feature_semantic_source_audit.json'),
 approvals:read('test/fixtures/v390_review4_feature_semantic_source_approvals.json')});
const unexpected=Object.keys({...manifest,...next}).filter(k=>k!=='inventorySha256'&&!isDeepStrictEqual(manifest[k],next[k]));
assert.equal(unexpected.length,0,'문서 hash 외 변경: '+unexpected.join(','));
assert.notEqual(next.inventorySha256,manifest.inventorySha256);
writeImplementationManifest(rootDir,next);assert(isDeepStrictEqual(read(manifestPath),next));
console.log(JSON.stringify({definitionRowsUnchanged:rows.length,manifestItemsUnchanged:next.items.length,
 approvalAndSemanticEvidenceUnchanged:true,onlyChangedField:'inventorySha256',previous:manifest.inventorySha256,current:next.inventorySha256}));

// 기존 공식 생성/쓰기 API를 사용하며 문서 hash 이외의 변동이 있으면 저장하지 않는다.
import fs from 'node:fs';
import assert from 'node:assert/strict';
import {execFileSync} from 'node:child_process';
import {generateImplementationManifest,parseFeatureRows,writeImplementationManifest} from '<repo>/scripts/internal/feature_implementation_manifest_lib.mjs';
const rootDir='<repo>';
const inventory='docs/project-feature-test-inventory.md',file='test/fixtures/project_feature_implementation_evidence.json';
const original=execFileSync('git',['show','HEAD:'+inventory],{cwd:rootDir,encoding:'utf8'});
const inventoryText=fs.readFileSync(rootDir+'/'+inventory,'utf8');
const rows=parseFeatureRows(inventoryText);
assert.equal(rows.length,986);assert.deepEqual(rows,parseFeatureRows(original));
const before=JSON.parse(fs.readFileSync(rootDir+'/'+file,'utf8'));
const generated=generateImplementationManifest({rootDir,inventoryText,rows});
assert.deepEqual({...generated,inventorySha256:before.inventorySha256},before,'문서 hash 외 변경은 이 갱신 범위 아님');
assert.notEqual(generated.inventorySha256,before.inventorySha256);
writeImplementationManifest(rootDir,generated);
assert.deepEqual(JSON.parse(fs.readFileSync(rootDir+'/'+file,'utf8')),generated);
console.log(JSON.stringify({definitionRowsUnchanged:rows.length,manifestItemsUnchanged:generated.items.length,
 approvalAndSemanticEvidenceUnchanged:true,onlyChangedField:'inventorySha256',
 previous:before.inventorySha256,current:generated.inventorySha256}));

import fs from 'node:fs';import path from 'node:path';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
const [id,cmd,...args]=process.argv.slice(2),dir=path.dirname(new URL(import.meta.url).pathname);
if(fs.existsSync(dir+'/'+id+'.json'))throw Error('중복 실행 ID');
const start=new Date().toISOString(),t=performance.now(),r=spawnSync(cmd,args,{cwd:'<repo>',timeout:180000,maxBuffer:30000000});
const metadata={id,cmd,args,start,end:new Date().toISOString(),elapsedMs:Math.round(performance.now()-t),exit:r.status,signal:r.signal,error:r.error?.code??null};
for(const s of ['stdout','stderr']){const b=r[s]??Buffer.alloc(0);fs.writeFileSync(dir+'/'+id+'.'+s+'.txt',b);metadata[s+'Sha256']=createHash('sha256').update(b).digest('hex');}
fs.writeFileSync(dir+'/'+id+'.json',JSON.stringify(metadata,null,2)+'\n');console.log(JSON.stringify(metadata));const out=(r.stdout??'').toString();console.log(out.split('\n').filter(l=>l.startsWith('[fail]')).join('\n'));console.log(out.slice(-1400));console.error((r.stderr??'').toString().slice(-3000));process.exit(r.status??1);
